<template>
 <article class="stock-management-row">
  <button type="button" :data-material-details="material.id" class="stock-row-name" :aria-label="`ดูรายละเอียด ${material.name}`" @click="$emit('details',material.id)"><span class="stock-row-emoji" aria-hidden="true">{{ material.emoji }}</span><span><strong>{{ material.name }}</strong><span class="stock-row-meta"><StatusBadge :data-inventory-type="material.inventoryType" :label="getMaterialKindLabel(material)" tone="neutral"/><MaterialUsage compact :usage="usage"/></span><small v-if="trackingMode!=='none'&&material.lastStockInDate">{{ material.hasSubRecipe?'ผลิตล่าสุด':'รับล่าสุด' }} {{ formatDisplayDate(material.lastStockInDate) }}<template v-if="trackingMode==='expiry_and_receive'&&material.expiryDate"> · หมดอายุ {{ formatDisplayDate(material.expiryDate) }}</template></small></span></button>
  <div class="stock-row-quantity"><small>คงเหลือ</small><strong>{{ number(material.stock) }} <span>{{ material.unit }}</span></strong><small v-if="draftDiff" class="stock-row-draft">รอยืนยัน {{ draftDiff>0?'+':'' }}{{ number(draftDiff) }} {{ material.unit }}</small><small v-if="material.packSize>1">≈ {{ number(Number(material.stock||0)/material.packSize) }} {{ material.packUnit }}</small><StatusBadge :label="status" :tone="tone"/></div>
  <div class="stock-row-cost"><small>ต้นทุน / {{ material.packUnit||material.unit }}</small><strong>฿{{ number(packCost) }}</strong><small v-if="material.packSize>1||material.hasSubRecipe">฿{{ number(material.unitCost) }} / {{ material.unit }}</small></div>
  <div class="stock-row-value"><small>มูลค่าคงเหลือ</small><strong>฿{{ money(Math.max(0,Number(material.stock)||0)*Number(material.unitCost||0)) }}</strong><Button class="stock-row-lots" variant="quiet" size="compact" :aria-label="`ดูล็อต ${material.name}`" @click="$emit('details',material.id)">{{ lotCount }} ล็อต</Button></div>
  <div class="stock-row-actions"><Button v-if="!material.isDeleted" :disabled="disabled" variant="secondary" :aria-label="`${material.hasSubRecipe?'ผลิต':'รับเข้า'} ${material.name}`" @click="$emit('receive',material.id)">{{ material.hasSubRecipe?'ผลิต':'รับเข้า' }}</Button><IconButton v-if="!supportedOnly" :label="`งานเพิ่มเติม ${material.name}`" :aria-expanded="moreOpen" @click="$emit('more',material.id,$event)"><MoreHorizontal :size="20" aria-hidden="true"/></IconButton></div>
 </article>
</template>
<script setup>
import {computed} from 'vue'
import {isExpired,formatDisplayDate} from '@/stores/posStore'
import {MoreHorizontal} from 'lucide-vue-next'
import Button from '../ui/Button.vue'
import IconButton from '../ui/IconButton.vue'
import StatusBadge from '../ui/StatusBadge.vue'
import MaterialUsage from './MaterialUsage.vue'
import {getMaterialKindLabel} from '@/domain/materialClassification'
const props=defineProps({material:{type:Object,required:true},usage:Object,draftDiff:{type:Number,default:0},packCost:{type:Number,default:0},lotCount:{type:Number,default:0},trackingMode:String,moreOpen:Boolean,supportedOnly:Boolean,disabled:Boolean})
defineEmits(['details','receive','more'])
const status=computed(()=>props.material.isDeleted?'จัดเก็บแล้ว':isExpired(props.material)?'หมดอายุแล้ว':props.material.stock<=0?'หมดสต็อก':props.material.stock<=props.material.minAlert?'ใกล้หมด':'ปกติ')
const tone=computed(()=>props.material.isDeleted?'neutral':isExpired(props.material)||props.material.stock<=0?'error':props.material.stock<=props.material.minAlert?'warning':'success')
const number=value=>Number(value||0).toLocaleString('th-TH',{maximumFractionDigits:2})
const money=value=>Number(value||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})
</script>
<style scoped>
.stock-management-row{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(110px,.8fr) minmax(100px,.6fr) minmax(110px,.6fr) auto;align-items:center;gap:20px;padding:20px;border-bottom:1px solid var(--border-subtle);min-width:0}.stock-management-row:last-child{border:0}.stock-row-name{display:flex;align-items:center;gap:14px;min-width:0;text-align:left;min-height:48px;border-radius:12px;cursor:pointer}.stock-row-name>span:last-child{min-width:0}.stock-row-name strong{display:block;font-size:.875rem;font-weight:600;line-height:1.6;overflow-wrap:anywhere}.stock-row-emoji{display:grid;place-items:center;flex-shrink:0;width:56px;height:56px;background:var(--bg-soft);border-radius:12px;font-size:28px}.stock-row-meta{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin:6px 0}.stock-row-name small,.stock-row-quantity>small,.stock-row-cost>small,.stock-row-value>small{display:block;font-size:.75rem;color:var(--text-muted);line-height:1.7;overflow-wrap:anywhere}.stock-row-quantity,.stock-row-cost,.stock-row-value{min-width:0;display:grid;gap:4px;justify-items:start}.stock-row-quantity>strong{font-size:1.125rem;color:var(--accent-brand);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.stock-row-quantity strong>span{font-size:.75rem;font-weight:400;color:var(--text-muted)}.stock-row-cost>strong,.stock-row-value>strong{font-size:.875rem;font-weight:600;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.stock-row-quantity .stock-row-draft{color:var(--state-warning);font-weight:500}.stock-row-actions{display:flex;align-items:center;gap:4px}.stock-row-name:focus-visible{outline:2px solid var(--accent-brand);outline-offset:3px}@media(max-width:1199px){.stock-management-row{grid-template-columns:minmax(0,1fr) minmax(140px,.6fr) auto;gap:16px}.stock-row-name{grid-column:1/-1}.stock-row-quantity{grid-row:2;grid-column:1}.stock-row-cost{grid-row:3;grid-column:1}.stock-row-value{grid-column:2;grid-row:2/4}.stock-row-actions{grid-column:3;grid-row:2/4}}@media(max-width:639px){.stock-management-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px;padding:16px}.stock-row-emoji{width:48px;height:48px;font-size:26px}.stock-row-name{align-items:flex-start}.stock-row-quantity{grid-row:2;grid-column:1}.stock-row-cost{grid-row:3;grid-column:1}.stock-row-value{grid-row:2;grid-column:2}.stock-row-actions{grid-row:3;grid-column:2;justify-self:end}}
</style>
<style scoped>.stock-row-meta{gap:4px 10px;margin:8px 0}.stock-row-lots{font-size:.75rem;font-weight:400;color:var(--text-muted);padding-inline:0;min-height:32px;background:transparent}</style>
